+		agentWidth    = 20
+		statusWidth   = 10
+		durationWidth = 8
+		tokensWidth   = 8
+		minWidth      = agentWidth + statusWidth + durationWidth + tokensWidth + 8 // four two-space separators
+	)
+	termWidth := m.termWidth
